package Simultaneous {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute log: int = 0;
    operation run() {
      initial A;
      state A {
        after 2ms to B { log = log * 10 + 1; }
        on receive a.x(v) to C { log = log * 10 + 2; }
      }
      state B {
        on receive a.x(v) to C { log = log * 10 + 3; }
        on receive a.y(v) to A { log = log * 10 + 4; }
        after 1ms to A { log = log * 10 + 5; }
      }
      state C {
        after 1ms to A { log = log * 10 + 6; }
        on receive a.go() to A { log = log * 10 + 7; }
        on receive a.y(v) to C { }
      }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    operation emit() { wait 2ms; publish q.x(1); wait 1ms; publish q.y(2); publish q.go(); wait 3ms; publish q.x(3); publish q.go(); }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  connect (s.q, m.a);
}

package SelfRestart {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute entries: int = 0;
    attribute exits: int = 0;
    attribute fired: int = 0;
    operation run() {
      initial A;
      state A {
        on entry { entries = entries + 1; }
        on exit { exits = exits + 1; }
        after 3ms to B { fired = fired + 1; }
        on receive a.x(v) to A { }
        on receive a.y(v) to A { }
        on receive a.go() to A { }
      }
      state B { after 3ms to A { fired = fired + 10; } }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    operation emit() { for (var i: int = 0; i < 4; i = i + 1) { wait 2ms; publish q.x(i); } wait 2ms; publish q.y(0); publish q.go(); }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  connect (s.q, m.a);
}

package Discards {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute taken: int = 0;
    operation run() {
      initial A;
      state A {
        on receive a.x(v) when (v > 5) to B { taken = taken + v; }
        on receive a.x(v) when (v < 0) to B { taken = taken - v; }
        on receive a.go() to B { }
      }
      state B {
        on receive a.y(v) to A { taken = taken + 100 * v; }
      }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    operation emit() { publish q.x(1); publish q.x(2); wait 1ms; publish q.x(9); wait 1ms; publish q.x(7); publish q.go(); wait 1ms; publish q.y(1); publish q.y(2); wait 1ms; publish q.go(); }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  connect (s.q, m.a);
}

package Ordered {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute path: int = 0;
    attribute level: int = 0;
    operation run() {
      initial A;
      state A {
        on receive a.x(v) when (v > level + 2) to B { path = path * 10 + 1; level = v; }
        on receive a.x(v) when (v > level) to C { path = path * 10 + 2; level = v; }
        on receive a.x(v) to A { path = path * 10 + 3; }
        on receive a.y(v) to A { }
        on receive a.go() to A { }
      }
      state B {
        after 2ms to C { path = path * 10 + 4; }
        after 2ms to A { path = path * 10 + 5; }
        after 1ms to B { path = path * 10 + 6; }
      }
      state C {
        after 1ms to A { path = path * 10 + 7; }
      }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    operation emit() { publish q.x(1); wait 3ms; publish q.x(9); wait 10ms; publish q.x(3); wait 5ms; publish q.x(9); if (false) { publish q.y(0); publish q.go(); } }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  connect (s.q, m.a);
}

package Suspending {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  port def Api { provides operation ask(v: int) returns int; }
  component def Server {
    port api: Api;
    attribute asked: int = 0;
    operation answer(v: int) returns int { asked = asked + 1; wait 2ms; return v * 2; }
    schedule { on call api.ask(v) answer(v); }
  }
  component def M {
    port a: In;
    reversed port srv: Api;
    attribute log: int = 0;
    attribute got: int = 0;
    operation run() {
      initial A;
      state A {
        on entry { wait 5ms; log = log * 10 + 1; }
        on exit { got = srv.ask(21); log = log * 10 + 2; }
        after 2ms to B { log = log * 10 + 3; }
        on receive a.x(v) to B { log = log * 10 + 4; }
      }
      state B {
        on entry { var more: int = srv.ask(1); got = got + more; }
        on receive a.x(v) to A { log = log * 10 + 5; }
        on receive a.y(v) to B { log = log * 10 + 6; }
        on receive a.go() to A { log = log * 10 + 7; }
        after 10ms to A { }
      }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    operation emit() { wait 1ms; publish q.x(1); wait 5ms; publish q.y(2); wait 1ms; publish q.go(); }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  component server: Server;
  connect (s.q, m.a);
  connect (m.srv, server.api);
}

package Family {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute count: int = 0;
    operation run() {
      initial Idle;
      state Idle {
        on receive a.x(v) to Busy { count = count + v; }
        on receive a.y(v) to Idle { count = count - v; }
        on receive a.go() to Idle { }
      }
      state Busy {
        after 2ms to Idle { count = count * 2; }
      }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    attribute k: int = 1;
    operation emit() { publish q.x(k); publish q.x(k + 1); wait 3ms; publish q.y(k); publish q.go(); }
    schedule { on start emit(); }
  }
  component def Sys {
    component m: M[3];
    component s: S[3];
    connect (s[0].q, m[0].a);
    connect (s[1].q, m[1].a);
    connect (s[2].q, m[2].a);
  }
  component sys: Sys;
}

package defer {
  enum Kind { defer, other }
  datatype R { defer: int; }
  port def In { requires event defer(defer: int); requires attribute level: int; }
  port def Out { provides event defer(defer: int); provides attribute level: int; }
  component def Machine {
    port defer: In;
    attribute total: int = 0;
    attribute kind: Kind = Kind.defer;
    operation run() {
      initial defer;
      state defer {
        on entry { var r: R = record R { defer = total; }; total = r.defer + 1; }
        on receive defer.defer(d) to to { var x: int = d; total = total + x; }
        on receive defer.level(v) to defer { total = total + 1000 * v; }
      }
      state to {
        on receive defer.level(v) to 'after' { total = total + 10 * v; }
        on receive defer.defer(d) to to { }
      }
      state 'after' {
        on receive defer.defer(d) to defer { kind = Kind.other; }
        on receive defer.level(v) to 'after' { }
      }
    }
    schedule { on start run(); }
  }
  component def Src {
    port o: Out;
    attribute defer: int = 1;
    operation go() { var defer2: int = defer + 1; publish o.defer(defer2); wait 1ms; send o.level(defer); wait 1ms; publish o.defer(3); }
    schedule { on start go(); }
  }
  component def Helper {
    attribute seen: int = 0;
    operation defer(defer: int) returns int { var d: int = defer * 2; return d; }
    operation use() { seen = defer(4); }
    schedule { on start use(); }
  }
  component c: Machine;
  component s: Src;
  component h: Helper;
  connect defer (s.o, c.defer);
}

package Statements {
  datatype R { defer: int; n: int; }
  port def In { requires event e(v: int); }
  port def Out { provides event e(v: int); }
  component def M {
    port p: In;
    attribute defer: int = 0;
    attribute rec: R = record R { defer = 0; n = 0; };
    operation bump(v: int) returns int { return v + 1; }
    operation run() {
      initial A;
      state A {
        on entry { defer = defer + 1; rec = record R { defer = defer; n = rec.n; }; }
        on receive p.e(v) to B { defer = bump(defer); rec = record R { defer = rec.defer; n = v; }; }
      }
      state B {
        on entry { var defer2: int = defer; defer = defer2 * 10; }
        after 1ms to A { defer = defer + 2; }
      }
    }
    schedule { on start run(); }
  }
  component def S { port q: Out; operation emit() { publish q.e(5); wait 2ms; publish q.e(6); } schedule { on start emit(); } }
  component m: M;
  component s: S;
  connect (s.q, m.p);
}

package Words {
  port def In { requires event 'when'(v: int); requires event to(v: int); requires event 'after'(); }
  port def Out { provides event 'when'(v: int); provides event to(v: int); provides event 'after'(); }
  component def M {
    port to: In;
    attribute 'when': int = 0;
    attribute after2: int = 0;
    operation run() {
      initial 'when';
      state 'when' {
        on receive to.'when'(v) when (v > 0) to to { 'when' = v; }
        on receive to.to(v) to 'after' { after2 = v; }
        on receive to.'after'() to 'when' { }
        after 5ms to to { }
      }
      state to {
        on receive to.to(v) to 'when' { after2 = after2 + v; }
        after 1ms to 'after' { }
      }
      state 'after' {
        on receive to.'after'() to 'when' { 'when' = 'when' * 10; }
        on receive to.'when'(v) to 'after' { }
      }
    }
    schedule { on start run(); }
  }
  component def S { port q: Out; operation emit() { publish q.'when'(3); wait 3ms; publish q.'after'(); wait 1ms; publish q.to(4); } schedule { on start emit(); } }
  component m: M;
  component s: S;
  connect (s.q, m.to);
}

package defer::defer {
  port def Q { provides event e(); }
  component def Unit { reversed port q: Q; attribute n: int = 0; operation h() { n = n + 1; } schedule { on receive q.e() h(); } }
}
package Cases {
  import defer::defer;
  port def P { provides event e(); }
  component def Actor { port p: P; }
  component def Box { reversed port p: P; attribute n: int = 0; operation h() { n = n + 1; } schedule { on receive p.e() h(); } }
  requirement Req { attribute limit: int = 1; }
  component box: Box;
  component actor: Actor;
  connect (actor.p, box.p);
  associate actor to defer;
  test defer of box { publish actor.p.e(); wait 1ms; assert box.n == 1; }
  verify Req by defer;
}

package Bad {
  port def In { requires event defer(); requires event x(); requires event other(); }
  component def M {
    port defer: In;
    operation run() {
      initial begin;
      state begin {
        on receive defer.defer() to unused { }
        on receive defer.x() to nowhere { }
      }
      state defer { on receive defer.x() to begin { } }
      state unused { on receive defer.x() to begin { } }
      final state done { on exit { } on receive defer.x() to begin { } }
    }
    schedule { on start run(); }
  }
  component m: M;
}

package BadStates {
  port def In { requires event e(v: int); }
  component def M {
    port p: In;
    attribute n: int = 0;
    operation bump() returns bool { n = n + 1; return true; }
    operation run(k: int) {
      initial missing;
      state A {
        on entry { n = 1; }
        on entry { n = 2; }
        on receive p.e(v) when (bump()) to A { return; }
        after 0ms to A { }
      }
    }
    operation other() {
      initial B;
      state B { on receive p.e(v) when (v) to B { } }
    }
    schedule { on start run(1); on start other(); }
  }
  component m: M;
}

package Owners {
  port def In { requires event e(v: int); requires event f(); }
  component def M {
    port p: In;
    attribute n: int = 0;
    operation h(v: int) { n = v; }
    operation run() {
      initial A;
      state A { on receive p.e(v) to A { n = n + 1; } }
    }
    schedule { on start run(); on receive p.e(v) h(v); }
  }
  component m: M;
}

package External {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute n: int = 0;
    attribute taken: int = 0;
    operation tick() { n = n + 1; }
    operation run() {
      initial A;
      state A {
        on receive a.x(v) when (n > 3) to B { taken = taken + 1; }
        on receive a.y(v) to A { }
        on receive a.go() to A { }
      }
      state B {
        on receive a.go() to A { }
      }
    }
    schedule { on start run(); on every 1ms tick(); }
  }
  component def S {
    port q: Out;
    operation emit() { for (var i: int = 0; i < 8; i = i + 1) { publish q.x(i); wait 1ms; } publish q.go(); publish q.y(0); }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  connect (s.q, m.a);
}

package Timers {
  component def M {
    attribute order: int = 0;
    operation run() {
      initial A;
      state A {
        on entry { order = order * 10 + 1; }
        after 1ms to B { order = order * 10 + 2; }
        after 1ms to C { order = order * 10 + 3; }
      }
      state B {
        on entry { wait 3ms; order = order * 10 + 4; }
        after 1ms to C { }
        after 2ms to A { }
      }
      state C {
        after 5ms to done { }
      }
      final state done { on entry { order = order * 10 + 9; } }
    }
    schedule { on start run(); }
  }
  component m: M;
}

package Driven {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute state2: int = 0;
    operation run() {
      initial Off;
      state Off {
        on receive a.go() to On { state2 = 1; }
        on receive a.x(v) to Off { }
        on receive a.y(v) to Off { }
      }
      state On {
        on receive a.x(v) when (v > 0) to On { state2 = state2 + v; }
        on receive a.y(v) to Off { state2 = 0 - v; }
        after 5ms to Off { state2 = 100; }
      }
    }
    schedule { on start run(); }
  }
  component def Driver { port q: Out; }
  component m: M;
  component driver: Driver;
  connect (driver.q, m.a);
  associate driver to 'Drive';
  test 'Drive' of m {
    publish driver.q.go();
    wait 1ms;
    publish driver.q.x(2);
    publish driver.q.x(0);
    wait 1ms;
    assert m.state2 == 3;
    wait 10ms;
    assert m.state2 == 100;
    publish driver.q.go();
    publish driver.q.y(4);
    wait 1ms;
    assert m.state2 == 0 - 4;
  }
}

package QueueOrder {
  port def In { requires event x(v: int); requires event y(v: int); requires event go(); }
  port def Out { provides event x(v: int); provides event y(v: int); provides event go(); }
  component def M {
    port a: In;
    attribute log: int = 0;
    operation run() {
      initial Idle;
      state Idle {
        on receive a.y(v) to Busy { log = log * 10 + v; }
        on receive a.x(v) to Busy { log = log * 10 + v; }
        on receive a.go() to Idle { }
      }
      state Busy {
        on entry { wait 3ms; }
        after 1ms to Idle { }
      }
    }
    schedule { on start run(); }
  }
  component def S {
    port q: Out;
    operation emit() { publish q.y(1); wait 1ms; publish q.x(2); wait 1ms; publish q.y(3); wait 1ms; publish q.go(); wait 5ms; publish q.x(4); publish q.y(5); }
    schedule { on start emit(); }
  }
  component m: M;
  component s: S;
  connect (s.q, m.a);
}
